import{_ as s,o as i,c as e,ak as t}from"./chunks/framework.B-zz2iUS.js";const k=JSON.parse('{"title":"什么是 SenRi FFI？","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/what-is-senri-ffi.md","filePath":"zh/guide/what-is-senri-ffi.md","lastUpdated":0}'),n={name:"zh/guide/what-is-senri-ffi.md"};function d(l,a,r,h,o,p){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="什么是-senri-ffi" tabindex="-1">什么是 SenRi FFI？ <a class="header-anchor" href="#什么是-senri-ffi" aria-label="Permalink to “什么是 SenRi FFI？”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p><strong>SenRi FFI</strong>（千里 FFI）是一个<strong>跨运行时 FFI（外部函数接口）统一抽象库</strong>，让你用同一套 API 在 KossJS、Node.js 和 Bun 三个 JavaScript 运行时上调用原生 C 动态库。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>不同运行时各自提供了不同的 FFI API（KossJS 的 <code>_senri_ffi</code>、Bun 的 <code>Bun.ffi</code>、Node.js 依赖 <code>koffi</code>）。SenRi FFI 在这些底层 API 之上提供一个统一的抽象层，使得编写一次 FFI 代码即可在三个运行时上运行。</p></div><h2 id="开源协议" tabindex="-1">开源协议 <a class="header-anchor" href="#开源协议" aria-label="Permalink to “开源协议”">​</a></h2><p>本项目采用 <a href="https://www.apache.org/licenses/LICENSE-2.0" target="_blank" rel="noreferrer">Apache 2.0</a> 协议开源发布。</p><h2 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to “问题背景”">​</a></h2><p>在 JavaScript 生态中调用原生 C 库，不同运行时的做法完全不同：</p><table tabindex="0"><thead><tr><th>运行时</th><th>FFI 方式</th><th>类型名称示例</th></tr></thead><tbody><tr><td>KossJS</td><td><code>globalThis._senri_ffi</code>（内置）</td><td><code>int32</code></td></tr><tr><td>Bun</td><td><code>Bun.ffi</code>（内置）</td><td><code>i32</code></td></tr><tr><td>Node.js</td><td><code>koffi</code>（需安装）</td><td><code>koffi.int32</code></td></tr></tbody></table><p>直接在代码中使用运行时的原生 API 会锁死你的代码到某个特定运行时。SenRi FFI 解决了这个问题。</p><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to “技术架构”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>        您的应用程序 (JavaScript / TypeScript)</span></span>
<span class="line"><span>                      ↓</span></span>
<span class="line"><span>            SenRi FFI (统一 API 层)</span></span>
<span class="line"><span>                      ↓</span></span>
<span class="line"><span>          ┌───────────┼───────────┐</span></span>
<span class="line"><span>          ↓           ↓           ↓</span></span>
<span class="line"><span>     KossJSAdapter  BunAdapter  NodeAdapter</span></span>
<span class="line"><span>          ↓           ↓           ↓</span></span>
<span class="line"><span>     _senri_ffi    Bun.ffi      koffi</span></span>
<span class="line"><span>    (内置 FFI)    (内置 FFI)   (可选安装)</span></span></code></pre></div><h3 id="适配器模式" tabindex="-1">适配器模式 <a class="header-anchor" href="#适配器模式" aria-label="Permalink to “适配器模式”">​</a></h3><p>SenRi FFI 使用<strong>适配器模式</strong>：</p><ol><li>定义统一的抽象接口 (<code>BaseAdapter</code>)</li><li>三个运行时各自实现适配器： <ul><li><code>KossJSAdapter</code> — 包装 <code>globalThis._senri_ffi</code></li><li><code>BunAdapter</code> — 包装 <code>Bun.ffi</code></li><li><code>NodeAdapter</code> — 包装 <code>koffi</code>（懒加载）</li></ul></li><li>启动时通过 <code>detectRuntime()</code> 自动选择合适的适配器</li></ol><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to “核心特性”">​</a></h2><h3 id="统一类型系统" tabindex="-1">统一类型系统 <a class="header-anchor" href="#统一类型系统" aria-label="Permalink to “统一类型系统”">​</a></h3><p>使用 <code>types.int32</code>、<code>types.cstring</code> 等统一名称，各适配器自动映射为运行时原生类型：</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { types } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;senri_ffi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 在所有运行时上都一样</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">types.int32   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// KossJS: &#39;int32&#39;, Bun: &#39;i32&#39;, Node: koffi.int32</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">types.float64 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// KossJS: &#39;float64&#39;, Bun: &#39;f64&#39;, Node: koffi.double</span></span></code></pre></div><h3 id="结构体-指针-数组" tabindex="-1">结构体 / 指针 / 数组 <a class="header-anchor" href="#结构体-指针-数组" aria-label="Permalink to “结构体 / 指针 / 数组”">​</a></h3><p>支持复合类型描述符：</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { pointer, array } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;senri_ffi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pointer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(types.int32);    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 指向 int32 的指针</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(types.uint8, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// uint8[256]</span></span></code></pre></div><h3 id="回调自动管理" tabindex="-1">回调自动管理 <a class="header-anchor" href="#回调自动管理" aria-label="Permalink to “回调自动管理”">​</a></h3><p>通过 <code>FinalizationRegistry</code> 自动释放 C 回调，防止内存泄漏。</p><h3 id="统一错误类型" tabindex="-1">统一错误类型 <a class="header-anchor" href="#统一错误类型" aria-label="Permalink to “统一错误类型”">​</a></h3><p>所有运行时抛出统一的 <code>FFIError</code> / <code>FFITypeError</code>，便于统一处理。</p><h2 id="支持的运行时" tabindex="-1">支持的运行时 <a class="header-anchor" href="#支持的运行时" aria-label="Permalink to “支持的运行时”">​</a></h2><table tabindex="0"><thead><tr><th>运行时</th><th>版本要求</th><th>FFI 后端</th><th>说明</th></tr></thead><tbody><tr><td>KossJS</td><td>—</td><td><code>_senri_ffi</code>（内置）</td><td>直接使用</td></tr><tr><td>Bun</td><td>&gt;= 1.0</td><td><code>Bun.ffi</code>（内置）</td><td>直接使用</td></tr><tr><td>Node.js</td><td>&gt;= 18</td><td><code>koffi</code>（需安装）</td><td><code>npm install koffi</code></td></tr></tbody></table><h2 id="运行时检测优先级" tabindex="-1">运行时检测优先级 <a class="header-anchor" href="#运行时检测优先级" aria-label="Permalink to “运行时检测优先级”">​</a></h2><p>SenRi FFI 按以下优先级自动检测运行时：</p><ol><li><strong>KossJS</strong> — 如果 <code>globalThis._senri_ffi</code> 为真值</li><li><strong>Bun</strong> — 如果 <code>Bun.ffi</code> 可用</li><li><strong>Node.js</strong> — 如果 <code>process.versions.node</code> 存在</li></ol><p>检测发生在模块首次加载时，之后使用缓存的适配器实例。</p><hr><p><strong>下一步</strong>:</p><ul><li><a href="/SenRiFFI/zh/guide/getting-started.html">快速开始</a> - 立即开始使用 SenRi FFI</li><li><a href="/SenRiFFI/zh/api/API-overview.html">API 概览</a> - 了解所有可用 API</li></ul>`,35)])])}const f=s(n,[["render",d]]);export{k as __pageData,f as default};
